source("R/r_packages_server.R",local=TRUE)
pc_r_help <- function() shiny::tagList(
 shiny::h3('Advanced R analysis: beyond the presets'),
 shiny::p('Write an R script or ask the AI Assistant to draft one. Review the code, data selection and scientific assumptions, then choose Run reviewed script. Drafting, loading and opening a study never execute its code.'),
 shiny::tags$ol(
  shiny::tags$li('Open a data table, then choose Advanced R analysis at the end of the Analysis method menu, or use Advanced R in the top toolbar. Load a template or write your script. Opening Advanced R does not change the selected preset or run a script. data is a copied data frame with automatic numeric conversion; data_raw retains the original cell text. Column names stay unchanged.'),
  shiny::tags$li('List any required packages, separated by commas. The app checks your bundled and personal R libraries. Choose Check / install packages to review missing packages and required dependencies from CRAN; installation starts only after Approve & install. The script does not run automatically afterward. stats supports GLMs and many methods beyond the presets. Compatible Mac/Windows binaries install into a library for your user account; bundled app packages and system R are unchanged. Source builds and non-CRAN repositories are not installed by this workflow.'),
  shiny::tags$li('Assign result <- list(tables=list(Name=data.frame(...)), plot=my_plot, text="Interpretation"). plot can be a ggplot object or a function drawing a base R plot. Return up to ten nonempty tables, each within the 10,000-row / 50-column table limit. Large combined outputs are rejected.'),
  shiny::tags$li('Run in a separate R process; Stop cancels it. The selected time limit is at most five minutes. Figures export as 3 × 3 inch SVG/PDF; use ggplot theme text size 7 for matching typography. Scripts can override their plot appearance.'),
  shiny::tags$li('Save draft keeps code and an input snapshot in this study. Runs save code, the exact input copy, package versions, console, tables and figures. Save the study to retain these records. Loading a saved analysis lets you rerun its saved input or the active table; results are historical snapshots, not live linked analyses.'),
  shiny::tags$li('Choose a returned table and Add result as data table to use normal graph/analysis tools. Importing results does not establish independence or validate the selected model. Review warnings, missing values, convergence and uncertainty.')),
 shiny::p(class='inline-note','Review code before running: custom R runs locally with your account permissions. The separate process protects the app session from ordinary errors; it is not an operating-system security sandbox. Do not run untrusted code.'),
 shiny::p('Open examples/Advanced R teaching example.rdatacraft for original count and independent-group data with three saved drafts. No script runs when you open it.'),
 shiny::p('Examples: the summary template returns means and SD; custom rank comparison returns a rank test and interval; the GLM template fits count responses while accounting for treatment and batch. Edit its formula and verify dispersion/design assumptions. Mixed-effects or other package methods become available after you approve installation of compatible packages. Stop can cancel downloading or staging; incomplete app-managed changes are rolled back. Approvals apply only to the displayed list and are never saved as blanket permission.'),
 shiny::p('AI workflow: request an Advanced R script, review the proposed script in the assistant, choose Open in Advanced R, then review and run. The draft keeps its original table as an input snapshot. Uncheck the snapshot option to use the active table instead. Check script validates syntax and package availability without execution. Ask AI for help opens a draft message for you to review and send. The AI never executes the proposed script automatically.'))
pc_r_ui <- function() shiny::tagList(
 shiny::div(class='page-heading',shiny::div(shiny::h1('Advanced R analysis'),shiny::p('Review a script, check packages, then run locally with an exact input snapshot.'))),
 shiny::div(class='r-workflow-steps',shiny::span('1 · Review script & input'),shiny::span('2 · Check packages'),shiny::span('3 · Run & inspect results')),
 shiny::div(class='r-workbench',
 shiny::div(class='card-surface r-editor',
  shiny::div(class='r-analysis-tools',shiny::selectInput('r_template','Starting template',setNames(names(pc_r_templates()),vapply(pc_r_templates(),function(t)t$title,character(1)))),shiny::actionButton('r_load_template','Load template'),shiny::actionButton('r_help','Analysis guide…')),
  shiny::div(class='r-input-summary',shiny::textOutput('r_input_context'),shiny::checkboxInput('r_use_saved','Use the loaded draft / analysis input snapshot',FALSE)),
  shiny::textInput('r_title','Analysis name','Custom R analysis'),
  shiny::textAreaInput('r_code','R script',pc_r_templates()$summary$code,rows=16,width='100%'),
  shiny::div(class='r-analysis-tools',shiny::actionButton('r_check_script','Check script'),shiny::actionButton('r_ask_ai','Ask AI for help…'),shiny::actionButton('r_save_draft','Save draft in study')),
  shiny::textInput('r_packages','Required packages (comma separated)',''),
  shiny::div(class='r-analysis-tools',shiny::actionButton('r_pkg_check','Check / install packages…'),shiny::tags$details(shiny::tags$summary('Package installation log'),shiny::verbatimTextOutput('r_pkg_log'))),
  shiny::p(class='inline-note','Missing packages require your approval. Installing packages never starts the script.'),
  shiny::div(class='r-run-bar',shiny::selectInput('r_timeout','Time limit',c('30 seconds'=30,'2 minutes'=120,'5 minutes'=300),selected=120),shiny::tags$button(id='r_run',type='button',class='btn btn-primary','Run reviewed script'),shiny::actionButton('r_stop','Stop',disabled='disabled')),
  shiny::div(role='status',`aria-live`='polite',shiny::textOutput('r_status')),
  shiny::tags$details(shiny::tags$summary('Live run progress'),shiny::verbatimTextOutput('r_progress')),
  shiny::p(class='inline-note','⌘ / Ctrl + Enter runs the reviewed script. Custom R has your account permissions; review code before running. data and data_raw are independent copies of the selected input.')),
 shiny::div(class='card-surface r-results-panel',shiny::h3('Saved analyses & results'),
  shiny::selectInput('r_saved','Saved analysis',choices=c('No saved analyses'='')),
  shiny::div(class='r-analysis-tools',shiny::actionButton('r_load_saved','Load saved analysis'),shiny::actionButton('r_delete','Delete selected…'),shiny::downloadButton('r_export_script','R script'),shiny::downloadButton('r_export_report','Analysis report')),
  shiny::uiOutput('r_results'),
  shiny::selectInput('r_result_table','Result table',choices=character()),
  shiny::div(class='r-analysis-tools',shiny::actionButton('r_import_table','Add result as data table'),shiny::downloadButton('r_export_table','Table CSV'),shiny::downloadButton('r_export_svg','Figure SVG'),shiny::downloadButton('r_export_pdf','Figure PDF')))))
pc_r_server <- function(input,output,session,capture,records,set_records,open_page,add_result,ask_ai=NULL) {
 runner<-pc_r_runner();loaded<-shiny::reactiveVal(NULL);status<-shiny::reactiveVal('Load a template, write a script, or ask the AI Assistant to draft one.');busy<-shiny::reactiveVal(FALSE)
 packages<-pc_pkg_server(input,output,session,request=function() {code<-pc_r_script(input$r_code);list(code=code,packages=pc_pkg_requirements(code,input$r_packages))},blocked=busy,status=status)
 selected<-shiny::reactive({x<-records();i<-suppressWarnings(as.integer(input$r_saved));if(length(i)!=1 || is.na(i) || i<1 || i>length(x)) NULL else x[[i]]})
 publish<-function(r) {x<-records();x[[length(x)+1L]]<-r;set_records(pc_r_records(x));loaded(r);shiny::updateSelectInput(session,'r_saved',selected=as.character(length(x)))}
 finish<-function(r) {busy(FALSE);tryCatch({publish(r);status(paste('R',r$result$status,'·',round(r$result$seconds,2),'seconds. Save the study to keep this record.'))},error=function(e) status(conditionMessage(e)))}
 poll<-function() {if(!busy()) return();r<-runner$poll();if(is.null(r)) later::later(function() shiny::withReactiveDomain(session,shiny::isolate(poll())),.2) else finish(r)}
 open<-function() {open_page();invisible(TRUE)}
 draft<-function(r) {if(busy() || packages$busy()) stop('Stop the current operation before loading another draft.');packages$reset();shiny::updateTextInput(session,'r_title',value=r$title);shiny::updateTextInput(session,'r_packages',value=r$packages);shiny::updateTextAreaInput(session,'r_code',value=r$code);snapshot<-if(!is.null(r$source)) pc_r_record(r$title,r$code,r$packages,r$source$table,r$source$name) else NULL;loaded(snapshot);shiny::updateCheckboxInput(session,'r_use_saved',value=!is.null(snapshot));status(if(is.null(snapshot)) 'AI draft loaded for review. It has not been executed.' else paste('AI draft loaded with an input snapshot of',snapshot$source_name,'. Review before running.'));session$sendCustomMessage('rdatacraft-review-r',list());open()}
 shiny::observeEvent(input$advanced_open,open())
 show_help<-function() shiny::showModal(shiny::modalDialog(title='Advanced R analysis guide',shiny::div(class='r-analysis-guide',pc_r_help()),size='l',easyClose=TRUE,fade=FALSE))
 shiny::observeEvent(input$r_help,show_help())
 shiny::observeEvent(input$r_help_from_examples,show_help())
 shiny::observeEvent(input$r_load_template,{if(busy() || packages$busy()) {status('Stop the current operation before loading a template.');return()};packages$reset();t<-pc_r_templates()[[input$r_template]];shiny::req(t);shiny::updateTextInput(session,'r_title',value=t$title);shiny::updateTextInput(session,'r_packages',value=t$packages);shiny::updateTextAreaInput(session,'r_code',value=t$code);shiny::updateCheckboxInput(session,'r_use_saved',value=FALSE);loaded(NULL);status('Template loaded. Review the code and study design before running.')})
 shiny::observeEvent(records(),{x<-records();choices<-if(!length(x)) c('No saved analyses'='') else setNames(as.character(seq_along(x)),vapply(x,function(r) paste(r$title,'·',if(is.null(r$result)) 'draft' else r$result$status,'·',r$created),character(1)));old<-shiny::isolate(input$r_saved);shiny::updateSelectInput(session,'r_saved',choices=choices,selected=if(length(x)) as.character(length(x)) else '')})
 record_input<-function(values=NULL) {values<-if(is.null(values)) input else values;if(!isTRUE(capture()$open)) stop('Create or open a study first.');c<-capture();r<-loaded();if(isTRUE(values$r_use_saved)) {if(is.null(r)) stop('Load an AI draft or saved analysis before using its input snapshot.');tab<-pc_read_text(r$source_tsv,'\t');name<-r$source_name} else {tab<-c$table;name<-c$name};pc_r_record(values$r_title,values$r_code,values$r_packages,tab,name)}
 attempt<-function(expr) tryCatch(force(expr),error=function(e) status(conditionMessage(e)))
 run_script<-function(values=NULL) attempt({values<-if(is.null(values)) input else values;if(busy() || packages$busy()) stop('Stop the current operation first.');if(length(records())>=20) stop('Export/remove an older saved analysis before adding another.');r<-record_input(values);missing<-pc_pkg_missing(pc_pkg_requirements(r$code,r$packages));if(length(missing)) stop(paste('Missing packages:',paste(missing,collapse=', '),'· choose Check / install packages to review and approve.'));runner$start(r,as.numeric(values$r_timeout));busy(TRUE);status('R is running in a separate process…');later::later(function() shiny::withReactiveDomain(session,shiny::isolate(poll())),.2)})
 shiny::observeEvent(input$r_submit,run_script(input$r_submit))
 shiny::observeEvent(input$r_run,run_script())
 shiny::observeEvent(input$r_stop,{if(packages$busy()) packages$cancel() else if(busy()) finish(runner$cancel())})
 shiny::observeEvent(input$r_save_draft,attempt({if(busy() || packages$busy()) stop('Finish or stop the current operation before saving another draft.');publish(record_input());status('Draft saved in this study. Save the study file to keep it.')}))
 shiny::observeEvent(input$r_load_saved,attempt({if(busy() || packages$busy()) stop('Stop the current operation before loading a saved analysis.');packages$reset();r<-selected();if(is.null(r)) stop('Choose a saved analysis.');loaded(r);shiny::updateTextInput(session,'r_title',value=r$title);shiny::updateTextInput(session,'r_packages',value=r$packages);shiny::updateTextAreaInput(session,'r_code',value=r$code);shiny::updateCheckboxInput(session,'r_use_saved',value=TRUE);status('Saved code and input selected. Nothing has executed.')}))
 shiny::observeEvent(input$r_delete,{if(busy() || packages$busy()) {status('Stop the current operation before deleting an analysis.');return()};shiny::req(selected());shiny::showModal(shiny::modalDialog(title='Delete saved R analysis?',fade=FALSE,shiny::p('This removes the selected script and stored result record from this study.'),footer=shiny::tagList(shiny::modalButton('Cancel'),shiny::actionButton('r_confirm_delete','Delete analysis',class='btn-danger'))))})
 shiny::observeEvent(input$r_confirm_delete,{if(busy() || packages$busy()) {status('Stop the current operation before deleting an analysis.');return()};x<-records();r<-selected();shiny::req(r);set_records(Filter(function(y) !identical(y$id,r$id),x));loaded(NULL);shiny::removeModal()})
 shiny::observeEvent(input$r_check_script,attempt({
  if(busy() || packages$busy()) stop('Stop the current operation first.')
  r<-record_input();required<-pc_pkg_requirements(r$code,r$packages);missing<-pc_pkg_missing(required)
  status(if(length(missing)) paste('Syntax valid. Missing packages:',paste(missing,collapse=', '),'· choose Check / install packages to review.') else paste('Syntax valid ·',r$source_name,'· required packages available. Review the method and code before running.'))
 }))
 shiny::observeEvent(input$r_ask_ai,attempt({
  if(busy() || packages$busy()) stop('Stop the current operation first.')
  if(is.null(ask_ai)) stop('AI Assistant is unavailable in this session.')
  code<-pc_r_text(input$r_code,30000);message<-paste0('Help me review or improve this Advanced R script for the active table. Ask about the scientific design if needed. Return an r_analysis draft if changing code. Required packages: ',substr(if(is.null(input$r_packages)) '' else input$r_packages,1,400),'\n\n',if(nchar(code)>4000) '[Script excerpt: first 4,000 characters. Ask for the rest before assuming this is the complete script.]\n' else '',substr(code,1,4000))
  source<-loaded();if(isTRUE(input$r_use_saved) && !is.null(source)) message<-paste0(message,'\n\nEditor input is the saved snapshot: ',substr(source$source_name,1,100),'. The assistant context describes the active table, which may differ. Ask me to confirm the intended source before adapting the script.')
  r<-selected();if(!is.null(r$result) && r$result$status!='success') message<-paste0(message,'\n\nLast saved run (may use a different script/input): ',substr(r$result$text,1,700))
  ask_ai(message);status('Draft message opened in AI Assistant. Review it and choose Send; nothing has been sent yet.')
 }))
 output$r_input_context<-shiny::renderText({
  c<-capture();r<-loaded()
  if(isTRUE(input$r_use_saved) && !is.null(r)) {tab<-pc_read_text(r$source_tsv,'\t');paste('Input snapshot:',r$source_name,'·',nrow(tab),'rows ×',ncol(tab),'columns')}
  else if(!isTRUE(c$open)) 'Create or open a study to select input data.'
  else paste('Active table:',c$name,'·',nrow(c$table),'rows ×',ncol(c$table),'columns · copied when you run')
 })
 output$r_progress<-shiny::renderText({shiny::invalidateLater(500,session);p<-runner$progress();if(is.null(p)) 'No R process is running.' else paste(paste0('Running · ',round(p$seconds),' / ',p$limit,' seconds'),p$console,sep='\n')})
 shiny::observe({session$sendCustomMessage('rdatacraft-r-state',list(busy=busy() || packages$busy()))})
 output$r_status<-shiny::renderText(status())
 output$r_results<-shiny::renderUI({r<-selected();if(is.null(r)) return(shiny::p('No saved result selected.'));z<-r$result
  shiny::tagList(shiny::p(paste('Input snapshot:',r$source_name,'·',r$created)),shiny::tags$details(shiny::tags$summary('Saved script and required packages'),shiny::tags$pre(r$code),shiny::p(r$packages)),if(is.null(z)) shiny::p('Draft only: not executed.') else shiny::tagList(shiny::p(paste('Status:',z$status,'·',z$r_version)),shiny::tags$pre(z$text),shiny::tags$details(shiny::tags$summary('Console and package versions'),shiny::tags$pre(z$console),shiny::tags$pre(paste(vapply(z$packages,function(p) paste(p$name,p$version),character(1)),collapse='\n'))),if(nzchar(z$svg)) shiny::tags$img(class='r-result-figure',src=paste0('data:image/svg+xml;base64,',jsonlite::base64_enc(charToRaw(z$svg))),alt='Advanced R result figure'),lapply(z$tables,function(t) {tab<-pc_read_text(t$data_tsv,'\t');shiny::tagList(shiny::h4(t$name),shiny::p(paste(nrow(tab),'rows; preview shows the first 50.')),shiny::div(class='r-result-table',shiny::tags$table(class='table',shiny::tags$thead(shiny::tags$tr(lapply(names(tab),shiny::tags$th))),shiny::tags$tbody(lapply(seq_len(min(nrow(tab),50)),function(i) shiny::tags$tr(lapply(tab,function(x) shiny::tags$td(if(is.na(x[i])) '—' else x[i]))))))))})))})
 shiny::observeEvent(selected(),{r<-selected();tables<-if(is.null(r)) list() else r$result$tables;shiny::updateSelectInput(session,'r_result_table',choices=if(length(tables)) setNames(as.character(seq_along(tables)),vapply(tables,function(t)t$name,character(1))) else character())},ignoreNULL=FALSE)
 chosen_table<-function() {r<-selected();shiny::req(r);i<-suppressWarnings(as.integer(input$r_result_table));if(length(i)!=1 || is.na(i) || i<1 || i>length(r$result$tables)) stop('Choose a result table.');r$result$tables[[i]]}
 shiny::observeEvent(input$r_import_table,attempt({t<-chosen_table();add_result(pc_read_text(t$data_tsv,'\t'),paste('R result ·',t$name));status('Added an independent editable data table. The saved R result remains a snapshot.')}))
 output$r_export_script<-shiny::downloadHandler(filename='rdatacraft-advanced-analysis.R',content=function(file) {r<-selected();shiny::req(r);writeLines(c(paste('# Input snapshot:',r$source_name),paste('# Required packages:',r$packages),'# data must be supplied as a data frame. See the saved study for exact input.',r$code),file,useBytes=TRUE)})
 output$r_export_table<-shiny::downloadHandler(filename='rdatacraft-r-result.csv',content=function(file) utils::write.csv(pc_read_text(chosen_table()$data_tsv,'\t'),file,row.names=FALSE))
 output$r_export_svg<-shiny::downloadHandler(filename='rdatacraft-r-figure.svg',content=function(file) {z<-selected()$result;shiny::req(nzchar(z$svg));writeLines(z$svg,file,useBytes=TRUE)},contentType='image/svg+xml')
 output$r_export_pdf<-shiny::downloadHandler(filename='rdatacraft-r-figure.pdf',content=function(file) {z<-selected()$result;shiny::req(nzchar(z$pdf));writeBin(jsonlite::base64_dec(z$pdf),file)},contentType='application/pdf')
 output$r_export_report<-shiny::downloadHandler(filename='rdatacraft-advanced-analysis.json',content=function(file) {r<-selected();shiny::req(r);jsonlite::write_json(r,file,auto_unbox=TRUE,pretty=TRUE,null='null')},contentType='application/json')
 session$onSessionEnded(runner$cleanup)
 list(open=open,draft=draft,runner=runner,packages=packages,busy=shiny::reactive(busy() || packages$busy()),selected=selected,status=status,reset=function() {packages$reset();runner$cleanup();busy(FALSE);loaded(NULL);shiny::updateCheckboxInput(session,'r_use_saved',value=FALSE);shiny::updateTextInput(session,'r_title',value='Custom R analysis');shiny::updateTextInput(session,'r_packages',value='');shiny::updateTextAreaInput(session,'r_code',value=pc_r_templates()$summary$code);status('Study loaded. Saved scripts have not been executed.')})
}
